package com.bank.region;

import java.util.*;
import java.util.logging.*;
import static java.util.Comparator.comparingDouble;
import static java.util.stream.Collectors.*;

public class GroupSortDemo {
    private static final Logger log = Logger.getLogger("Region");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "Mumbai", 1000000.0),
            new Employee("Amit", "Mumbai", 800000.0),
            new Employee("Priya", "Delhi", 250000.0),
            new Employee("Neha", "Delhi", 600000.0));
        RegionService service = new RegionService();

        Map<String, List<Employee>> byCity = service.byCitySortedBySalary(staff);
        byCity.forEach((city, list) -> log.info(() -> city + " → "
            + list.stream().map(Employee::getName).toList()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String city;
    private final double salary;
    Employee(String name, String city, double salary) {
            this.name = name;
            this.city = city
            this.salary = salary;
    }
    String getName() { return name; }
    String getCity() { return city; }
    double getSalary() { return salary; }
}

// ─── Would be in service/RegionService.java ───
class RegionService {
    Map<String, List<Employee>> byCitySortedBySalary(List<Employee> staff) {
        return staff.stream()
            .collect(groupingBy(
                Employee::getCity,                          // bucket by city
                collectingAndThen(toList(), list -> {        // then sort each bucket
                    list.sort(comparingDouble(Employee::getSalary).reversed()); // high→low
                    return list;
                })));
    }
}
